END_VAR
(* Main program logic *)
IF AutoMode THEN
    Phase := 1;
    CASE Phase OF
        1: (* Fill *)
            PumpOn := TRUE;
            ValveOpen := FALSE;
            IF Pressure > 80.0 THEN
                Phase := 2;
            END_IF;
        2: (* React *)
            PumpOn := FALSE;
            ValveOpen := FALSE;
            Temperature := Temperature + 1.0;
            IF Temperature > Setpoint THEN
                Phase := 3;
            END_IF;
